import React, { useMemo, useState } from "react";
import { Container, Modal } from "react-bootstrap";
import Particle from "../Particle";
import { useInViewOnce } from "../../hooks/useInViewOnce";
import { useTranslation } from "react-i18next";
import { certificationTimeline } from "../../data/certifications";

function sortByYearAsc(items) {
  return [...items].sort((a, b) => (a.year ?? 0) - (b.year ?? 0));
}

const STATUS_CLASS = {
  earned: "is-earned",
  in_progress: "is-in-progress",
  planned: "is-planned",
};

export default function Certifications() {
  const header = useInViewOnce();
  const timelineRef = useInViewOnce();
  const { t, i18n } = useTranslation();
  const [activeId, setActiveId] = useState(null);

  const isFr = i18n.language?.toLowerCase().startsWith("fr");

  const items = useMemo(() => sortByYearAsc(certificationTimeline), []);

  const active = useMemo(
    () => items.find((c) => c.id === activeId) ?? null,
    [activeId, items]
  );

  const legend = [
    { status: "earned", label: t("certs.legend_earned") },
    { status: "in_progress", label: t("certs.legend_in_progress") },
    { status: "planned", label: t("certs.legend_planned") },
  ];

  return (
    <Container fluid className="cert-section">
      <Particle />
      <Container>
        <div
          ref={header.ref}
          className={`cert-header section-card reveal ${header.isInView ? "is-visible" : ""}`}
        >
          <div className="section-header">
            <h1 className="section-title">
              {t("certs.title_prefix")}{" "}
              <span className="purple">{t("certs.title_highlight")}</span>
            </h1>
            <p className="section-subtitle">{t("certs.subtitle")}</p>
          </div>

          <div className="cert-legend">
            {legend.map((l) => (
              <span key={l.status} className={`cert-legend-item ${STATUS_CLASS[l.status]}`}>
                <span className="cert-legend-dot" aria-hidden="true" />
                {l.label}
              </span>
            ))}
          </div>
        </div>

        <div
          ref={timelineRef.ref}
          className={`section-card reveal ${timelineRef.isInView ? "is-visible" : ""}`}
        >
          <div className="cert-timeline-h-wrap">
            <div className="cert-timeline-h" role="list">
              <div className="cert-timeline-h-line" aria-hidden="true" />
              {items.map((c) => {
                const title = isFr ? (c.title_fr ?? c.title) : c.title;
                const issuer = isFr ? (c.issuer_fr ?? c.issuer) : c.issuer;
                return (
                  <div
                    key={c.id}
                    className={`cert-node ${STATUS_CLASS[c.status] ?? ""}`}
                    role="listitem"
                  >
                    <div className="cert-node-marker" aria-hidden="true" />
                    <div className="cert-node-year">{c.year}</div>
                    <button
                      type="button"
                      className="cert-node-title"
                      onClick={() => setActiveId(c.id)}
                    >
                      {title}
                    </button>
                    <div className="cert-node-issuer">{issuer}</div>
                  </div>
                );
              })}
            </div>
          </div>
          <p className="cert-hint">{t("certs.click_hint")}</p>
        </div>

        {active && (
          <Modal
            show
            onHide={() => setActiveId(null)}
            centered
            contentClassName="skill-modal cert-modal"
          >
            <Modal.Header closeButton>
              <Modal.Title>
                {isFr ? (active.title_fr ?? active.title) : active.title}
              </Modal.Title>
            </Modal.Header>
            <Modal.Body>
              <div className="cert-modal-meta">
                <span className={`cert-modal-badge ${STATUS_CLASS[active.status]}`}>
                  {t(`certs.legend_${active.status}`)}
                </span>
                <span className="cert-modal-year">{active.year}</span>
                <span className="cert-modal-issuer">
                  {isFr ? (active.issuer_fr ?? active.issuer) : active.issuer}
                </span>
              </div>

              <h3 className="cert-modal-heading">{t("certs.modal_what")}</h3>
              <p className="cert-modal-text">
                {isFr ? (active.summary_fr ?? active.summary) : active.summary}
              </p>

              <h3 className="cert-modal-heading">{t("certs.modal_why")}</h3>
              <p className="cert-modal-text">
                {isFr ? (active.purpose_fr ?? active.purpose) : active.purpose}
              </p>
            </Modal.Body>
          </Modal>
        )}
      </Container>
    </Container>
  );
}
